const fs   = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const BACKEND  = path.join('D:\\', 'full stack', 'node project', 'jwt');
const FRONTEND = path.join('D:\\', 'full stack', 'CRM V2');

const green  = (s) => `\x1b[32m${s}\x1b[0m`;
const yellow = (s) => `\x1b[33m${s}\x1b[0m`;
const cyan   = (s) => `\x1b[36m${s}\x1b[0m`;
const red    = (s) => `\x1b[31m${s}\x1b[0m`;
const bold   = (s) => `\x1b[1m${s}\x1b[0m`;

function writeFile(filePath, content) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(filePath, content, 'utf8');
  console.log(green('  ✓') + ' ' + filePath);
}

function checkDir(dirPath, name) {
  if (!fs.existsSync(dirPath)) {
    console.log(red(`  ✗ Dossier introuvable : ${dirPath}`));
    console.log(red(`    Vérifiez le chemin du projet ${name}`));
    process.exit(1);
  }
}

// ── Vérification des projets ──────────────────────────────────────────
console.log(bold(cyan('\n╔══════════════════════════════════════╗')));
console.log(bold(cyan('║  Dashboard Export Afrique – Install  ║')));
console.log(bold(cyan('╚══════════════════════════════════════╝\n')));

